template:
% 视觉归一化：把最长边缩放到 6 个坐标单位（默认 1 单位 = 1cm，即最长边恒约 6cm；参数声明区由系统按参数值自动生成）；
% 只缩放坐标，线宽、字体、虚线样式保持不变；直角记号、角弧等装饰尺寸已除以 figscale 补偿，不随归一化缩小。
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ac)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % 三个顶点
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \pgfmathsetmacro{\Cx}{\ac*cos(\anglea)}
  \pgfmathsetmacro{\Cy}{\ac*sin(\anglea)}
  \coordinate (C) at (\Cx,\Cy);
  % 三边中点：D=BC中点, E=AC中点, F=AB中点
  \pgfmathsetmacro{\Dx}{(\ab + \Cx)/2}
  \pgfmathsetmacro{\Dy}{\Cy/2}
  \coordinate (D) at (\Dx,\Dy);
  \pgfmathsetmacro{\Ex}{\Cx/2}
  \pgfmathsetmacro{\Ey}{\Cy/2}
  \coordinate (E) at (\Ex,\Ey);
  \coordinate (F) at (\ab/2,0);
  % 三角形三边
  \draw[thick] (A) -- (B) -- (C) -- cycle;
  % ∠A 角弧（朝三角形内部，开直角记号时不画角弧）
  \ifnum\showangle>0
    \ifnum\rightmarka=0
      \pgfmathsetmacro{\arcr}{min(0.4/\figscale, \ab*0.18, \ac*0.18)}
      \draw[thick] (\arcr,0) arc[start angle=0, end angle=\anglea, radius=\arcr];
    \fi
  \fi
  % ∠A 直角记号（小正方形两边，朝三角形内部，∠A=90 时使用）
  \ifnum\rightmarka>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \ab*0.2, \ac*0.2)}
    \draw[thick] (\rmsz,0) -- (\rmsz,\rmsz) -- (0,\rmsz);
  \fi
  % ∠B 直角记号（B 在(\ab,0)，BA 沿-x，BC 斜向上）
  \ifnum\rightmarkb>0
    \pgfmathsetmacro{\rmszb}{min(0.3/\figscale, \ab*0.2, \Cy*0.2)}
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\rmbax}{\ab - \rmszb}
    \pgfmathsetmacro{\rmbcx}{\ab + (\Cx-\ab)/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbcy}{\Cy/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbmx}{\rmbax + (\Cx-\ab)/\bclen*\rmszb}
    \pgfmathsetmacro{\rmbmy}{\Cy/\bclen*\rmszb}
    \draw[thick] (\rmbax,0) -- (\rmbmx,\rmbmy) -- (\rmbcx,\rmbcy);
  \fi
  % ∠C 直角记号（C 在(\Cx,\Cy)，沿 CA、CB 两边方向）
  \ifnum\rightmarkc>0
    \pgfmathsetmacro{\rmszc}{min(0.3/\figscale, \ac*0.2, sqrt((\Cx-\ab)^2 + \Cy^2)*0.2)}
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\rmcax}{\Cx - \Cx/\ac*\rmszc}
    \pgfmathsetmacro{\rmcay}{\Cy - \Cy/\ac*\rmszc}
    \pgfmathsetmacro{\rmcbx}{\Cx + (\ab-\Cx)/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcby}{\Cy - \Cy/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcmx}{\rmcax + (\ab-\Cx)/\bclen*\rmszc}
    \pgfmathsetmacro{\rmcmy}{\rmcay - \Cy/\bclen*\rmszc}
    \draw[thick] (\rmcax,\rmcay) -- (\rmcmx,\rmcmy) -- (\rmcbx,\rmcby);
  \fi
  % 中线 AD（实线，从顶点 A 到 BC 中点 D）
  \ifnum\showmedianad>0
    \draw[thick] (A) -- (D);
  \fi
  % 中线 BE（实线，从顶点 B 到 AC 中点 E）
  \ifnum\showmedianbe>0
    \draw[thick] (B) -- (E);
  \fi
  % 中线 CF（实线，从顶点 C 到 AB 中点 F）
  \ifnum\showmediancf>0
    \draw[thick] (C) -- (F);
  \fi
  % 高线：A 到 BC，垂足 H（实线，垂足带直角记号；钝角时垂足落在 BC 延长线上）
  \ifnum\showheighta>0
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\sA}{\ab*(\ab-\Cx)/(\bclen*\bclen)}
    \pgfmathsetmacro{\Hx}{\ab + \sA*(\Cx-\ab)}
    \pgfmathsetmacro{\Hy}{\sA*\Cy}
    \draw[thick] (A) -- (\Hx,\Hy);
    \fill (\Hx,\Hy) circle [radius=1.6pt];
    \node[above right=3pt] at (\Hx,\Hy) {$\heightafoot$};
    \pgfmathsetmacro{\ahlen}{sqrt(\Hx*\Hx+\Hy*\Hy)}
    \pgfmathsetmacro{\ux}{(\Cx-\ab)/\bclen}
    \pgfmathsetmacro{\uy}{\Cy/\bclen}
    \pgfmathsetmacro{\vx}{-\Hx/\ahlen}
    \pgfmathsetmacro{\vy}{-\Hy/\ahlen}
    \pgfmathsetmacro{\rmh}{min(0.3/\figscale, \ahlen*0.2, \bclen*0.2)}
    \draw[thick] (\Hx+\rmh*\ux, \Hy+\rmh*\uy) -- (\Hx+\rmh*\ux+\rmh*\vx, \Hy+\rmh*\uy+\rmh*\vy) -- (\Hx+\rmh*\vx, \Hy+\rmh*\vy);
  \fi
  % 高线：B 到 AC，垂足（实线，带直角记号）
  \ifnum\showheightb>0
    \pgfmathsetmacro{\tB}{\ab*\Cx/(\ac*\ac)}
    \pgfmathsetmacro{\Px}{\tB*\Cx}
    \pgfmathsetmacro{\Py}{\tB*\Cy}
    \draw[thick] (B) -- (\Px,\Py);
    \fill (\Px,\Py) circle [radius=1.6pt];
    \node[left=3pt] at (\Px,\Py) {$\heightbfoot$};
    \pgfmathsetmacro{\wx}{\ab-\Px}
    \pgfmathsetmacro{\wy}{-\Py}
    \pgfmathsetmacro{\wlen}{sqrt(\wx*\wx+\wy*\wy)}
    \pgfmathsetmacro{\ux}{\Cx/\ac}
    \pgfmathsetmacro{\uy}{\Cy/\ac}
    \pgfmathsetmacro{\vx}{\wx/\wlen}
    \pgfmathsetmacro{\vy}{\wy/\wlen}
    \pgfmathsetmacro{\rmh}{min(0.3/\figscale, \wlen*0.2, \ac*0.2)}
    \draw[thick] (\Px+\rmh*\ux, \Py+\rmh*\uy) -- (\Px+\rmh*\ux+\rmh*\vx, \Py+\rmh*\uy+\rmh*\vy) -- (\Px+\rmh*\vx, \Py+\rmh*\vy);
  \fi
  % 高线：C 到 AB，垂足（实线，带直角记号）
  \ifnum\showheightc>0
    \draw[thick] (C) -- (\Cx,0);
    \fill (\Cx,0) circle [radius=1.6pt];
    \node[below=3pt] at (\Cx,0) {$\heightcfoot$};
    \pgfmathsetmacro{\rmh}{min(0.3/\figscale, \Cy*0.2)}
    \draw[thick] (\Cx-\rmh,0) -- (\Cx-\rmh,\rmh) -- (\Cx,\rmh);
  \fi
  % 角平分线：∠A 平分线交 BC（实线，交点画小圆点；按 BQ:QC=AB:AC 定分点）
  \ifnum\showbisectora>0
    \pgfmathsetmacro{\tA}{\ab/(\ab+\ac)}
    \pgfmathsetmacro{\Qx}{\ab + \tA*(\Cx-\ab)}
    \pgfmathsetmacro{\Qy}{\tA*\Cy}
    \draw[thick] (A) -- (\Qx,\Qy);
    \fill (\Qx,\Qy) circle [radius=1.6pt];
  \fi
  % 角平分线：∠B 平分线交 AC（实线，交点画小圆点；按 AQ:QC=AB:BC 定分点）
  \ifnum\showbisectorb>0
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\tB}{\ab/(\ab+\bclen)}
    \pgfmathsetmacro{\Rx}{\tB*\Cx}
    \pgfmathsetmacro{\Ry}{\tB*\Cy}
    \draw[thick] (B) -- (\Rx,\Ry);
    \fill (\Rx,\Ry) circle [radius=1.6pt];
  \fi
  % 角平分线：∠C 平分线交 AB（实线，交点画小圆点；按 AQ:QB=AC:BC 定分点）
  \ifnum\showbisectorc>0
    \pgfmathsetmacro{\bclen}{sqrt((\Cx-\ab)^2 + \Cy^2)}
    \pgfmathsetmacro{\tC}{\ac/(\ac+\bclen)}
    \pgfmathsetmacro{\Sx}{\tC*\ab}
    \draw[thick] (C) -- (\Sx,0);
    \fill (\Sx,0) circle [radius=1.6pt];
  \fi
  % 中位线（虚线，连接 D-E-F-D 构成中位线三角形）
  \ifnum\showmidseg>0
    \draw[dashed] (D) -- (E);
    \draw[dashed] (E) -- (F);
    \draw[dashed] (F) -- (D);
  \fi
  % 中点处画实心小圆点（绝对半径 1.6pt，不随坐标缩放，明确标出边上有个点）
  \ifnum\showd>0
    \fill (D) circle [radius=1.6pt];
  \fi
  \ifnum\showe>0
    \fill (E) circle [radius=1.6pt];
  \fi
  \ifnum\showf>0
    \fill (F) circle [radius=1.6pt];
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above=3pt] at (C) {$C$};
  % 中点标签：根据对应 bool 显示
  \ifnum\showd>0
    \node[above right=3pt] at (D) {$D$};
  \fi
  \ifnum\showe>0
    \node[left=3pt] at (E) {$E$};
  \fi
  \ifnum\showf>0
    \node[below=3pt] at (F) {$F$};
  \fi
\end{tikzpicture}
